mapper.select:
SELECT COUNT(*) FROM reservation
WHERE device_id = #{deviceId}
AND CAST(start_time AS DATE) = CAST(#{startTime} AS DATE)
AND (
(#{startTime} <= end_time AND #{endTime} >= start_time)
OR (#{startTime} <= end_time AND #{endTime} >= end_time)
OR (#{startTime} <= start_time AND #{endTime} >= start_time)
)

AND id != #{excludeId}
